def verifier_ip(s):
    parts = s.split('.')
    if len(parts) != 4:
        return False
    for p in parts:
        if not p.isdigit():
            return False
        if len(p) > 1 and p[0] == '0':  # reject leading zeros
            return False
        val = int(p)
        if not 0 <= val <= 255:
            return False
    return True
```

