def convertir_octets(n):
    """Convertit un nombre d'octets en Ko, Mo ou Go (1 Ko = 1024)."""
    if n < 0:
        raise ValueError("Le nombre d'octets doit être positif")
    ko = n / 1024
    mo = ko / 1024
    go = mo / 1024
    if go >= 1:
        return f"{go:.2f} Go"
    elif mo >= 1:
        return f"{mo:.2f} Mo"
    else:
        return f"{ko:.2f} Ko"
