def dichotomy(l, x):
    low, high = 0, len(l) - 1
    while low <= high:
        mid = (low + high) // 2
        if l[mid] == x:
            return mid
        elif x < l[mid]:
            high = mid - 1
        else:
            low = mid + 1
    return -1
